/// <summary>
/// N.Freidenberger 23.01.2025
/// </summary>
/// <param name = "_inventSum">_inventSum</param>
/// <returns>Qty</returns>
public static display  Qty   avaAvailableForShipmentPerLocationQty(InventSum      _inventSum)
{
    InventDim           dimValues, dimValuesParm; 
    Qty                 availForShipment;
    InventDimParm       inventDimParm;

    dimValues.data(_inventSum.joinChild());

    dimValuesParm.InventSiteId     = dimValues.InventSiteId;
    dimValuesParm.InventLocationId = dimValues.inventLocationId;

    if (InventSite::find(dimValuesParm.InventSiteId).AVAShippingAbility != AVAShippingAbility::No)
    {
        availForShipment = inventSum::avaPhysicalAvailAbilityForShipping(_inventSum.ItemId,dimValues);
    }
    else
    {
        InventOnhand        inventOnHand;
        inventDimParm.InventSiteIdFlag = NoYes::Yes;
        inventDimParm.InventLocationIdFlag = NoYes::Yes;

        inventOnHand = inventOnHand::newItemDim(_inventSum.ItemId,dimValues,inventDimParm);

        availForShipment =   inventOnHand.availPhysical();
    }

    return availForShipment;
}
